#!/usr/bin/env bash
# Rehearsal test bucket for the behavioural verification Job (B7, platform/rehearsal behavioral.py).
# RGW user bravo-rehearsal-verify (overlays/rke2/rook/rehearsal-verify.yaml) owns the bucket bravo-rehearsal-verify.
# Block Public Access is not set on this bucket on purpose: the Job must see what a proposed policy does by itself.
# Its control step first shows that an open policy is visible there (unsigned GET 200), so a later refusal is
# the policy's doing.
# The user's keys (generated by RGW in-cluster) go to the platform OpenBao secret/envs/<env>/rehearsal-s3 on a
# pipe, with the in-cluster endpoint, the RGW CA (public), the owner ARN, and the destination attachment bucket and
# its owner (the app identity). The platform maps that owner to the test owner when it renders a proposal for the
# test bucket. Nothing is written to disk. Run after install.sh step rgw (and again after a reinstall: RGW makes
# new keys).
#   rgw-rehearsal-bucket.sh <kube-context> [env-id]
set -euo pipefail
ctx=$1 env=${2:-target-onprem}
user=bravo-rehearsal-verify bucket=bravo-rehearsal-verify port=${RGW_PF_PORT:-18444}
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
keys="$(cd "$here/../../pilot/scripts" && pwd)/keys.sh"
k() { kubectl --context "$ctx" "$@"; }

k apply -f "$here/../overlays/rke2/rook/rehearsal-verify.yaml" >/dev/null
k -n rook-ceph wait --for=jsonpath='{.status.phase}'=Ready "cephobjectstoreuser/$user" --timeout=5m >/dev/null
secret="rook-ceph-object-user-bravo-$user"
app_user="$(k get objectbucket obc-chat-bravo-demo-attachments -o jsonpath='{.spec.additionalState.cephUser}')"
[[ -n $app_user ]] || { echo "rgw-rehearsal-bucket: owner of bravo-demo-attachments not found (ObjectBucket)" >&2; exit 1; }

work="$(mktemp -d)"; chmod 700 "$work"
# kubectl itself in the background (not the k function), so $! is the port-forward and the trap ends it.
kubectl --context "$ctx" -n rook-ceph port-forward svc/rook-ceph-rgw-bravo "$port:443" >"$work/pf.log" 2>&1 &
pf=$!
trap 'kill $pf 2>/dev/null || true; rm -rf "$work"' EXIT
k -n rook-ceph get configmap bravo-rgw-ca -o jsonpath='{.data.ca\.crt}' >"$work/ca.crt"   # public CA cert
for _ in $(seq 1 30); do grep -q Forwarding "$work/pf.log" && break; sleep 0.5; done

s3() {
  AWS_ACCESS_KEY_ID="$(k -n rook-ceph get secret "$secret" -o jsonpath='{.data.AccessKey}' | base64 -d)" \
  AWS_SECRET_ACCESS_KEY="$(k -n rook-ceph get secret "$secret" -o jsonpath='{.data.SecretKey}' | base64 -d)" \
  AWS_REGION=us-east-1 AWS_CA_BUNDLE="$work/ca.crt" AWS_REQUEST_CHECKSUM_CALCULATION=when_required \
  AWS_RESPONSE_CHECKSUM_VALIDATION=when_required AWS_PAGER="" AWS_CONFIG_FILE=/dev/null \
  AWS_SHARED_CREDENTIALS_FILE=/dev/null \
    env -u AWS_PROFILE -u AWS_SESSION_TOKEN aws --endpoint-url "https://localhost:$port" "$@"
}
if s3 s3api head-bucket --bucket "$bucket" >/dev/null 2>&1; then echo "rgw-rehearsal-bucket: $bucket exists; kept"
else s3 s3api create-bucket --bucket "$bucket" >/dev/null; echo "rgw-rehearsal-bucket: $bucket created (owner $user)"; fi
echo "rgw-rehearsal-bucket: public access block:"
s3 s3api get-public-access-block --bucket "$bucket" --output json 2>&1 | jq -c . 2>/dev/null || echo "  none (intended)"
echo "rgw-rehearsal-bucket: bucket policy:"
s3 s3api get-bucket-policy --bucket "$bucket" --output json 2>/dev/null | jq -r .Policy || echo "  none"

{ k -n rook-ceph get secret "$secret" -o json; k -n rook-ceph get configmap bravo-rgw-ca -o json; } \
  | jq -sc --arg b "$bucket" --arg u "$user" --arg app "$app_user" \
      '{access_key_id: (.[0].data.AccessKey | @base64d), secret_access_key: (.[0].data.SecretKey | @base64d),
        endpoint: "https://rook-ceph-rgw-bravo.rook-ceph.svc", bucket: $b, ca_pem: .[1].data["ca.crt"],
        owner_arn: ("arn:aws:iam:::user/" + $u), target_bucket: "bravo-demo-attachments",
        target_app_arn: ("arn:aws:iam:::user/" + $app)}' \
  | "$keys" env-put-json "$env" rehearsal-s3
